// === Tab: Grid ===
class Grid {
  constructor(w, h, sze) {
    this.w = w;
    this.h = h;
	 this.sze = sze;
    this.cells = new Map();
    this.dominos = [];
    this.ends = []; // exactly two ends

    this.failCount = 0;
    this.maxFails = 10;

    this.startNewChain();

  }

  startNewChain() {
    for (i = 0; i < 200; i++) {
      let x = floor(random(this.w));
      let y = floor(random(this.h));
      let dir = random([[1,0], [-1,0], [0,1], [0,-1]]);

      let nx = x + dir[0];
      let ny = y + dir[1];

      if (
        nx < 0 || ny < 0 ||
        nx >= this.w || ny >= this.h
      ) continue;

      // first cell must be fully isolated
      if (!this.isClearAll(x, y)) continue;

      // second cell: allow adjacency ONLY to the first
      if (!this.isClearAll(nx, ny, { x, y })) continue;

      let c1 = { x, y, value: floor(random(0,7)) };
      let c2 = { x: nx, y: ny, value: floor(random(0,7)) };

      this.addDomino([c1, c2]);
      this.activeEnds = [c1, c2];
      this.failCount = 0;
      return;
    }
  }

  key(x, y) {
    return `${x},${y}`;
  }

  has(x, y) {
    return this.cells.has(this.key(x, y));
  }


  isClearAll(x, y, allow = null) {
    if (this.has(x, y)) return false;

    for (dx = -1; dx <= 1; dx++) {
      for (dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;

        var nx = x + dx;
        var ny = y + dy;

        if (allow && nx === allow.x && ny === allow.y) continue;
        if (this.has(nx, ny)) return false;
      }
    }
    return true;
  }

  isClear(x, y, allow = null) {
    if (this.has(x, y)) return false;

    for (let n of [
      { x: x + 1, y },
      { x: x - 1, y },
      { x, y: y + 1 },
      { x, y: y - 1 }
    ]) {
      if (allow && n.x === allow.x && n.y === allow.y) continue;
      if (this.has(n.x, n.y)) return false;
    }
    return true;
  }


  addDomino(cells) {
    let d = new Domino(cells);
	 push();
	 translate(
      width / 2 - (this.w * this.sze) / 2,
      height / 2 - (this.h * this.sze) / 2
    );
	 d.draw(this.sze);
	 pop();
    for (c of cells) {
      this.cells.set(this.key(c.x, c.y), c.value);
    }
    this.dominos.push(d);
  }

  nextDomino() {
    let endIndex = floor(random(this.activeEnds.length));
    let end = this.activeEnds[endIndex];
    let { x, y, value } = end;

    let neighbors = [
      { x: x + 1, y },
      { x: x - 1, y },
      { x, y: y + 1 },
      { x, y: y - 1 }
    ].filter(n => this.has(n.x, n.y));

    if (neighbors.length !== 1) {
      this.failCount++;
      this.checkRestart();
      return;
    }

    let inDx = x - neighbors[0].x;
    let inDy = y - neighbors[0].y;

    let dirs = shuffle([
      { dx: inDx, dy: inDy },
      { dx: -inDy, dy: inDx },
      { dx: inDy, dy: -inDx }
    ], true);

    for ({ dx, dy } of dirs) {
      var nx = x + dx;
      var ny = y + dy;
      let fx = nx + dx;
      let fy = ny + dy;

      let connect = { x, y };

      if (
        nx < 0 || ny < 0 || fx < 0 || fy < 0 ||
        nx >= this.w || ny >= this.h ||
        fx >= this.w || fy >= this.h
      ) continue;

      // first cell: must touch ONLY the end
      if (!this.isClear(nx, ny, connect)) continue;

      // second cell: must be fully isolated
      if (!this.isClear(fx, fy)) continue;


      var c1 = { x: nx, y: ny, value };
      var c2 = { x: fx, y: fy, value: floor(random(0,7)) };

      this.addDomino([c1, c2]);
      this.activeEnds[endIndex] = c2;
      this.failCount = 0;
      return;
    }

    // no direction worked
    this.failCount++;
    this.checkRestart();
  }

  checkRestart() {
    if (this.failCount >= this.maxFails) {
      this.startNewChain();
    }
  }


  draw() {
    push();
    translate(
      width / 2 - (this.w * this.sze) / 2,
      height / 2 - (this.h * this.sze) / 2
    );

    stroke(220, 128);
	  if (false) {	  
	    for (x = 0; x <= this.w; x++)
	      line(x * this.sze, 0, x * this.sze, this.h * this.sze);
	    for (y = 0; y <= this.h; y++)
	      line(0, y * this.sze, this.w * this.sze,  y * this.sze);
	  }

    // for (d of this.dominos) d.draw(this.sze);
    pop();
  }
}


// === Tab: Domino ===
class Domino {
  constructor(cells) {
    this.cells = cells;
  }

  draw(SZE) {
    let a = this.cells[0];
    let b = this.cells[1];

    var x = min(a.x, b.x);
    var y = min(a.y, b.y);
    let w = a.x !== b.x ? 2 : 1;
    let h = a.y !== b.y ? 2 : 1;

	 const S2 = SZE/2;
	 const S8 = SZE/10; // it was before S/8

    push();
    translate(x * SZE + w * S2, y * SZE + h * S2);
	 rotate((noise(x, y)-0.5)/5)
    stroke("#1E1100");
    fill(16);
	 rectMode(CENTER); rect(0, 0, w * SZE - S8, h * SZE - S8, S8);

    stroke("tan");
	 let ox, oy;
    if (w === 2) {
		line(0, -S2+S8, 0, S2-S8);
		ox = -0.5;
		oy = 0;
	 }
    if (h === 2) {
		line(-S2+S8, 0, S2-S8, 0);
		ox = 0;
		oy = -0.5
	 }

    fill("tan");
    textAlign(CENTER, CENTER);
    textSize(16);

    for (c of this.cells) {
		/*
      text(
        c.value,
        (c.x - x + ox) * SZE,
        (c.y - y + oy) * SZE
      );
	  */
		pCircle((c.x - x + ox) * SZE, (c.y - y + oy) * SZE, SZE * 0.4, c.value);
    }
    pop();
  }
}

