function pCircle(x, y, r, pat = -1, params = {sw: 0, tf: 0}) {
  let sw = params.sw || r / 20; // stroke weight
  let pa = pat || params.p || -1; // pattern
  let tf = params.tf || 0; // time fraction

  // mask in shape
  push();
  clip(() => {
    circle(x, y, r + r);
    // rect(x - r, y - r, r + r, r + r)
  });

  noFill();
  stroke(196);
  strokeWeight(sw * 0.5);
	stroke(random(["tan", "gold", "#99C0E0", "white", "darkorange", "pink"]))

  // patterns
  switch (pa) {
    case 1: 
      { // outer circles
        for (cr = r - sw / 2; cr > 0; cr -= 1.41 * sw) {
			 //stroke("gold")
          circle(x, y, cr + cr);
        }
      }
      break;

    case 2:
      { // star
        const u = TWO_PI * 2 * r;
        const n = u / sw / 2 / 2;
        var a = TWO_PI / n;
        translate(x, y);
        rotate(frameCount * tf);
        strokeWeight(sw * 0.5);
		  //stroke("tan")
        for (i = 0; i < n; i++) {
          line(0, 0, r, 0);
          rotate(a);
        }
      }
      break;

    case 3:
      { // diagonal lines
        translate(x, y);
        rotate(frameCount * tf);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
		  //stroke("#99C0E0")
        for (i = 0; i <= r + r; i += sw + sw) {
          const l = r + r - i;
          line(i, 0, l + i, l);
          if (i) line(0, i, l, l + i);
        }
      }
      break;

    case 4:
      { // horiz + vert lines
        translate(x, y);
        rotate(frameCount * tf);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
		  //stroke("white")
        for (i = 0; i <= r + r; i += 1.41 * sw) {
          beginShape();
          vertex(0, i);
          vertex(r + r - i, i);
          vertex(r + r - i, r + r);
          endShape();
        }
      }
      break;

    case 5:
      { // zick zack lines
        var d = r * 0.25;
        translate(x, y);
        rotate(frameCount * tf);
        translate(-r, -r);
        strokeWeight(sw * 0.5);
		  //stroke("darkorange")
        for (i = -d; i <= r + r; i += sw + sw) {
          beginShape();
					for (j = 0; j < 9; j++) {
	          vertex(j * d, i + (j % 2) * d);
					}
          endShape();
        }
      }
      break;

    case 6:
      { // dotted 1
        translate(x, y);
        rotate(frameCount * tf);
        translate(sw - r, sw - r);
        strokeWeight(sw);
		  //stroke("pink")
        var n = (r / sw) * 2;
        for (i = 0; i <= n; i++) {
          for (j = 0; j <= n; j++) {
            if ((i + j) % 2) point(i * sw, j * sw);
          }
        }
      }
      break;

    case 7:
      { // dotted 2
        translate(x, y);
        rotate(frameCount * tf);
        translate(sw - r, sw - r);
        strokeWeight(sw);
		  //stroke("yellow")
        var n = r / sw;
        for (i = 0; i <= n; i++) {
          for (j = 0; j <= n; j++) {
            point(i * sw * 2, j * sw * 2);
          }
        }
      }
      break;

    case 8:
      { // dotted 3
        translate(x, y);
        rotate(frameCount * tf);
        translate(sw - r, sw - r);
        strokeWeight(sw);
        var n = r / sw;
        for (i = 0; i <= n; i++) {
          for (j = 0; j <= n; j++) {
            point(i * sw * 2, j * sw * 2 + (i % 2 ? 0 : sw));
          }
        }
      }
      break;

    default:
      circle(x, y, 2 * r - sw);
  }

  pop();
}

