var grid, NUM;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("randomly connected domino tiles with abstract pattern");
	frameRate(30);
	initGrid();
}

function initGrid() {
	NUM = ~~random(6, 11);
	const SZ = ~~(max(width, height) / NUM);
	const NX = ~~(width / SZ)
	const NY = ~~(height / SZ)
	grid = new Grid(NX, NY, ~~(SZ * 0.95));

	// for (i = 0; i < 99; i++) grid.nextDomino();

	noiseSeed(~~random(12345));

	background("#06242D");
}

function mousePressed() {
	initGrid();
}

function draw() {
	// background("#06242D");
	grid.draw();
	grid.nextDomino();
}
